


/** Independent redemption resource. Operational reservations are separate from immutable posted transactions. Captured value can be refunded only against its original redemption. */ export type GiftCardRedemption = { "capture_mode": "automatic" | "manual" | (string & {}); /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "captured_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** RFC3339 timestamp. Format: date-time. */ "expires_at": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id": string; "gift_card_id": string; "gift_card_redemption_id": string; "idempotency_key": string; "order_id": string | null; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "remaining_refundable_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "requested_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "reserved_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "status": "reserved" | "captured" | "canceled" | "expired" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "version": string; };
